create extension if not exists pgcrypto;
create type public.app_role as enum ('citizen','responder','hospital','shelter','volunteer','organization','administrator');
create type public.trust_status as enum ('VERIFIED','SIMULATED','UNVERIFIED','STALE','OFFLINE','SYNCING','USER-REPORTED');
create type public.incident_status as enum ('ACTIVE','STABILIZING','EMERGENCY','RECOVERY','CLOSED');
create type public.request_status as enum ('REQUESTED','TRIAGED','ASSIGNED','EN ROUTE','ARRIVED','RESOLVED');
create type public.severity as enum ('LOW','MODERATE','HIGH','CRITICAL');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role public.app_role not null default 'citizen', organization_id uuid, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null, kind text, verified boolean default false, created_at timestamptz default now());
alter table public.profiles add constraint profiles_org_fk foreign key (organization_id) references public.organizations(id);
create table public.incidents(id uuid primary key default gen_random_uuid(), code text unique not null, type text not null, severity public.severity not null, affected_area text, state text, district text, population integer default 0, risk_level text, status public.incident_status default 'ACTIVE', source text, trust public.trust_status default 'UNVERIFIED', last_updated timestamptz default now(), created_at timestamptz default now());
create table public.incident_zones(id uuid primary key default gen_random_uuid(), incident_id uuid references public.incidents(id) on delete cascade, geometry jsonb not null, zone_type text, created_at timestamptz default now());
create table public.emergency_requests(id uuid primary key default gen_random_uuid(), incident_id uuid references public.incidents(id), reporter_id uuid references public.profiles(id), status public.request_status default 'REQUESTED', people_count integer, incident_type text, requested_assistance jsonb default '[]', medical_need boolean default false, urgency public.severity default 'MODERATE', vulnerabilities jsonb default '[]', location jsonb, source text, trust public.trust_status default 'USER-REPORTED', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.request_messages(id uuid primary key default gen_random_uuid(), request_id uuid references public.emergency_requests(id) on delete cascade, sender_id uuid references public.profiles(id), body text, channel text default 'TEXT', created_at timestamptz default now());
create table public.request_evidence(id uuid primary key default gen_random_uuid(), request_id uuid references public.emergency_requests(id) on delete cascade, uploader_id uuid references public.profiles(id), kind text, storage_path text, metadata jsonb, trust public.trust_status default 'UNVERIFIED', created_at timestamptz default now());
create table public.responders(id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id), responder_code text unique not null, responder_type text, status text default 'AVAILABLE', organization_id uuid references public.organizations(id));
create table public.responder_locations(id uuid primary key default gen_random_uuid(), responder_id uuid references public.responders(id) on delete cascade, latitude double precision, longitude double precision, heading double precision, speed double precision, trust public.trust_status default 'VERIFIED', recorded_at timestamptz default now());
create table public.emergency_vehicles(id uuid primary key default gen_random_uuid(), code text unique not null, vehicle_type text, responder_id uuid references public.responders(id), status text, trust public.trust_status default 'VERIFIED');
create table public.vehicle_locations(id uuid primary key default gen_random_uuid(), vehicle_id uuid references public.emergency_vehicles(id) on delete cascade, latitude double precision, longitude double precision, heading double precision, eta_seconds integer, trust public.trust_status default 'VERIFIED', recorded_at timestamptz default now());
create table public.assignments(id uuid primary key default gen_random_uuid(), request_id uuid references public.emergency_requests(id), responder_id uuid references public.responders(id), vehicle_id uuid references public.emergency_vehicles(id), status text default 'ASSIGNED', assigned_by uuid references public.profiles(id), created_at timestamptz default now(), updated_at timestamptz default now());
create table public.resources(id uuid primary key default gen_random_uuid(), name text not null, category text not null, unit text default 'unit');
create table public.resource_inventory(id uuid primary key default gen_random_uuid(), resource_id uuid references public.resources(id), organization_id uuid references public.organizations(id), available integer default 0, reserved integer default 0, deployed integer default 0, trust public.trust_status default 'VERIFIED', updated_at timestamptz default now());
create table public.resource_requests(id uuid primary key default gen_random_uuid(), request_id uuid references public.emergency_requests(id), resource_id uuid references public.resources(id), quantity integer, status text default 'REQUESTED', created_at timestamptz default now());
create table public.resource_transfers(id uuid primary key default gen_random_uuid(), resource_id uuid references public.resources(id), from_organization_id uuid references public.organizations(id), to_organization_id uuid references public.organizations(id), quantity integer, status text default 'REQUESTED', approved_by uuid references public.profiles(id), created_at timestamptz default now(), updated_at timestamptz default now());
create table public.shelters(id uuid primary key default gen_random_uuid(), name text not null, organization_id uuid references public.organizations(id), latitude double precision, longitude double precision, capacity integer default 0, occupied integer default 0, food boolean default false, water boolean default false, medical_support boolean default false, accessibility boolean default false, status text default 'AVAILABLE', trust public.trust_status default 'VERIFIED', last_verified timestamptz default now());
create table public.hospitals(id uuid primary key default gen_random_uuid(), name text not null, organization_id uuid references public.organizations(id), latitude double precision, longitude double precision, beds integer default 0, critical_capacity integer default 0, medical_personnel integer default 0, supplies jsonb default '{}', status text default 'AVAILABLE', trust public.trust_status default 'VERIFIED', last_verified timestamptz default now());
create table public.volunteers(id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id), organization_id uuid references public.organizations(id), skills jsonb default '[]', location jsonb, availability boolean default true, verification_status text default 'PENDING');
create table public.alerts(id uuid primary key default gen_random_uuid(), incident_id uuid references public.incidents(id), level public.severity not null, affected_area text, valid_from timestamptz, valid_until timestamptz, instructions text, source text, trust public.trust_status default 'VERIFIED', created_by uuid references public.profiles(id), created_at timestamptz default now());
create table public.notification_preferences(profile_id uuid primary key references public.profiles(id) on delete cascade, push_enabled boolean default true, critical_enabled boolean default true, language text default 'en');
create table public.family_groups(id uuid primary key default gen_random_uuid(), owner_id uuid references public.profiles(id), name text, created_at timestamptz default now());
create table public.family_members(id uuid primary key default gen_random_uuid(), family_group_id uuid references public.family_groups(id) on delete cascade, profile_id uuid references public.profiles(id), invite_email text, status text default 'INVITED', safety_status text default 'PENDING', last_checkin timestamptz);
create table public.safe_status(id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id), family_group_id uuid references public.family_groups(id), status text not null, location jsonb, created_at timestamptz default now());
create table public.missing_persons(id uuid primary key default gen_random_uuid(), reported_by uuid references public.profiles(id), incident_id uuid references public.incidents(id), name text, description text, last_seen_location jsonb, evidence jsonb default '[]', status text default 'MISSING', verification_status text default 'PENDING', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.disaster_events(id uuid primary key default gen_random_uuid(), incident_id uuid references public.incidents(id), event_type text, event_time timestamptz default now(), description text, source text, trust public.trust_status default 'VERIFIED');
create table public.simulation_scenarios(id uuid primary key default gen_random_uuid(), name text, disaster_type text, state text, district text, affected_area text, severity public.severity, population integer, parameters jsonb default '{}', created_by uuid references public.profiles(id), created_at timestamptz default now());
create table public.simulation_events(id uuid primary key default gen_random_uuid(), scenario_id uuid references public.simulation_scenarios(id) on delete cascade, offset_minutes integer, event_type text, payload jsonb, created_at timestamptz default now());
create table public.simulation_snapshots(id uuid primary key default gen_random_uuid(), scenario_id uuid references public.simulation_scenarios(id) on delete cascade, offset_minutes integer, state jsonb, created_at timestamptz default now());
create table public.ai_analyses(id uuid primary key default gen_random_uuid(), subject_type text, subject_id uuid, analysis_type text, input_snapshot jsonb, output jsonb, confidence text, human_review_required boolean default true, created_at timestamptz default now());
create table public.verification_records(id uuid primary key default gen_random_uuid(), subject_type text, subject_id uuid, reviewer_id uuid references public.profiles(id), decision text, notes text, created_at timestamptz default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, subject_type text, subject_id uuid, source text, metadata jsonb, created_at timestamptz default now());
create table public.donation_campaigns(id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id), title text, goal_amount numeric, verified boolean default false, status text default 'ACTIVE', created_at timestamptz default now());
create table public.donation_transactions(id uuid primary key default gen_random_uuid(), campaign_id uuid references public.donation_campaigns(id), donor_id uuid references public.profiles(id), amount numeric, status text default 'RECEIVED', created_at timestamptz default now());
create table public.donation_usage(id uuid primary key default gen_random_uuid(), campaign_id uuid references public.donation_campaigns(id), amount numeric, description text, created_at timestamptz default now());
create table public.mesh_messages(id uuid primary key default gen_random_uuid(), sender_node text, recipient_node text, payload jsonb, status text default 'QUEUED', created_at timestamptz default now());
create table public.offline_queue(id uuid primary key default gen_random_uuid(), profile_id uuid references public.profiles(id), operation text, payload jsonb, status text default 'PENDING SYNC', conflict jsonb, created_at timestamptz default now(), synced_at timestamptz);
create table public.disaster_timeline(id uuid primary key default gen_random_uuid(), incident_id uuid references public.incidents(id) on delete cascade, event_time timestamptz default now(), label text, details text, source text, trust public.trust_status default 'VERIFIED');
create table public.recovery_projects(id uuid primary key default gen_random_uuid(), incident_id uuid references public.incidents(id), name text, status text default 'OPEN', progress integer default 0, resource_requirements jsonb default '{}', created_at timestamptz default now());

alter table public.profiles enable row level security;
alter table public.incidents enable row level security;
alter table public.emergency_requests enable row level security;
alter table public.audit_logs enable row level security;
create policy "profiles own row" on public.profiles for select using (auth.uid()=id);
create policy "profiles update own row" on public.profiles for update using (auth.uid()=id);
create policy "citizens can create requests" on public.emergency_requests for insert with check (auth.uid()=reporter_id);
create policy "requester can view own requests" on public.emergency_requests for select using (auth.uid()=reporter_id);
-- In production, add role-aware policies for responders/command using a security-definer role lookup function.
